node -e "
const initSqlJs = require('sql.js');
const fs = require('fs');
initSqlJs().then(SQL => {
  const buf = fs.readFileSync('/workspace/world.db');
  const db = new SQL.Database(buf);
  const res = db.exec('SELECT * FROM ts_reminders');
  if (res.length > 0) {
    console.log('Columns:', res[0].columns);
    res[0].values.forEach(r => console.log(JSON.stringify(r)));
  }
});"
